import{_ as a,o,c as s,a2 as t}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"The shared-object loader","description":"","frontmatter":{},"headers":[],"relativePath":"l1/solib-loader.md","filePath":"l1/solib-loader.md"}'),r={name:"l1/solib-loader.md"};function d(i,e,n,l,h,c){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="the-shared-object-loader" tabindex="-1">The shared-object loader <a class="header-anchor" href="#the-shared-object-loader" aria-label="Permalink to &quot;The shared-object loader&quot;">​</a></h1><p><code>ocos/l1apps/ld_so.c</code> - the in-tree dynamic loader (a ring-3 program itself, linked at 0x10000000 via <code>ld_so.ld</code>), used by the dynamic-linking user programs.</p><h2 id="what-it-handles" tabindex="-1">What it handles <a class="header-anchor" href="#what-it-handles" aria-label="Permalink to &quot;What it handles&quot;">​</a></h2><p>ELF dynamic objects: DT_NEEDED chains, symbol tables, relocation processing (R_X86_64_RELATIVE / GLOB_DAT / JUMP_SLOT / 64 families), init arrays at load, and unload with reference handling.</p><h2 id="the-image-modes" tabindex="-1">The image modes <a class="header-anchor" href="#the-image-modes" aria-label="Permalink to &quot;The image modes&quot;">​</a></h2><p><code>tools/gen_userprogs.py</code> preserves the v2.x build modes per program: ET_EXEC for the static apps, ET_DYN + <code>PT_INTERP=/lib/ld.so</code> for <code>dyn_hello</code> / <code>pie_test</code> / <code>so_test</code> / <code>dlsym_test</code> / <code>reloc_test</code> (the kernel rejects a silent ET_EXEC downgrade of a PIE program - image type is part of the interface).</p><h2 id="the-proof-it-works" tabindex="-1">The proof it works <a class="header-anchor" href="#the-proof-it-works" aria-label="Permalink to &quot;The proof it works&quot;">​</a></h2><p>The embedded fleet exercises every corner from ring 3:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; run dyn_hello           (loaded, init ran, hello printed)</span></span>
<span class="line"><span>ush&gt; run so_test             (foo_add(2,3)=5 through the solib)</span></span>
<span class="line"><span>ush&gt; run dlsym_test          (dlsym resolves foo_add(7,8)=15)</span></span>
<span class="line"><span>ush&gt; run pie_test            (loaded at 0x... - PIE base assignment)</span></span>
<span class="line"><span>ush&gt; run reloc_test          (foo_add=30 foo_global=42 fp=300)</span></span></code></pre></div><p>plus <code>l1test</code>&#39;s <code>ext_wp8b selftest 14/14</code> - the loader self-check that rides every regression run. If your program loads through this path, these are your regression anchors.</p><h2 id="position-independence" tabindex="-1">Position independence <a class="header-anchor" href="#position-independence" aria-label="Permalink to &quot;Position independence&quot;">​</a></h2><p>PIE objects relocate through the same relocation pass; the loader&#39;s base assignment is what lets the <code>-fno-pie</code> apps and PIE programs coexist in one registry - <code>pie_test</code>&#39;s source shows the exact relocation mix a dynamic program may carry.</p><h2 id="the-libfoo-leg" tabindex="-1">The libfoo leg <a class="header-anchor" href="#the-libfoo-leg" aria-label="Permalink to &quot;The libfoo leg&quot;">​</a></h2><p><code>libfoo.c</code> (the embedded solib) is built by <code>tools/build_solib.py</code> into <code>solib_data.h</code> - the same embed chain as every other program, so the staleness gate covers it.</p>`,14)])])}const b=a(r,[["render",d]]);export{m as __pageData,b as default};
